package org.rsmod.content.skills.construction

/**
 * POH rooms and furniture, loaded from `poh_rooms.tsv` (generated by
 * tools/construction/poh_data.py from the cache's poh_room / poh_hotspot / furniture dbrows, a scan
 * of the Rimmington-style room templates, and OSRS Wiki furniture xp and built loc ids).
 */
internal object ConstructionData {
    /** A buildable room: its template zone (Rimmington style) and door edges at rotation 0. */
    class Room(
        val key: String,
        val id: Int,
        val name: String,
        val level: Int,
        val coins: Int,
        val zoneX: Int,
        val zoneZ: Int,
        /** [EDGE_NORTH]..[EDGE_WEST]. */
        val doors: Set<Int>,
    ) {
        /** Door edges after the room is turned [rotation] quarter turns clockwise. */
        fun doors(rotation: Int): Set<Int> = doors.mapTo(HashSet()) { (it + rotation) and 3 }
    }

    /** A hotspot loc type placed in a room template, and the furniture group it belongs to. */
    class Spot(val room: String, val hotspot: String, val group: Int, val suffix: String)

    /** One furniture choice for a group; [locs] maps hotspot suffix to the built loc. */
    class Option(
        val room: String,
        val group: Int,
        val tier: Int,
        val name: String,
        val level: Int,
        val xp: Double,
        val materials: List<Pair<String, Int>>,
        val nails: Int,
        val icon: String,
        val locs: Map<String, String>,
    )

    const val EDGE_NORTH = 0
    const val EDGE_EAST = 1
    const val EDGE_SOUTH = 2
    const val EDGE_WEST = 3

    /** Saved room type ids (never reorder; 0 = empty slot). */
    private val roomIds =
        mapOf(
            "garden" to 1,
            "parlour" to 2,
            "kitchen" to 3,
            "dining" to 4,
            "workshop" to 5,
            "chapel" to 6,
            "portal" to 7,
            "hall" to 8,
        )

    private val lines: List<List<String>> by lazy {
        val input =
            ConstructionData::class.java.getResourceAsStream("poh_rooms.tsv")
                ?: error("Construction resource not found: poh_rooms.tsv")
        input
            .bufferedReader()
            .use { it.readLines() }
            .filter { it.isNotBlank() && !it.startsWith("#") }
            .map { it.split('\t') }
    }

    val rooms: List<Room> by lazy {
        lines
            .filter { it[0] == "room" }
            .map { p ->
                Room(
                    key = p[1],
                    id = roomIds.getValue(p[1]),
                    name = p[2],
                    level = p[3].toInt(),
                    coins = p[4].toInt(),
                    zoneX = p[5].toInt(),
                    zoneZ = p[6].toInt(),
                    doors = p[7].split(',').filter { it.isNotEmpty() }.map { it.toInt() }.toSet(),
                )
            }
    }

    val roomsByKey: Map<String, Room> by lazy { rooms.associateBy { it.key } }
    val roomsById: Map<Int, Room> by lazy { rooms.associateBy { it.id } }

    val spots: List<Spot> by lazy {
        lines
            .filter { it[0] == "spot" }
            .map { p -> Spot(p[1], p[2], p[3].toInt(), p.getOrElse(4) { "" }) }
    }

    val options: List<Option> by lazy {
        lines
            .filter { it[0] == "option" }
            .map { p ->
                Option(
                    room = p[1],
                    group = p[2].toInt(),
                    tier = p[3].toInt(),
                    name = p[4],
                    level = p[5].toInt(),
                    xp = p[6].toDouble(),
                    materials =
                        p[7]
                            .split(',')
                            .filter { it.isNotEmpty() }
                            .map { it.substringBefore(':') to it.substringAfter(':').toInt() },
                    nails = p[8].toInt(),
                    icon = p[9],
                    locs =
                        p[10].split(';').filter { it.isNotEmpty() }.associate {
                            it.substringBefore('=') to it.substringAfter('=')
                        },
                )
            }
    }

    /** Buildable options per room and group, by tier. */
    val optionsByGroup: Map<Pair<String, Int>, List<Option>> by lazy {
        options.groupBy { it.room to it.group }.mapValues { (_, v) -> v.sortedBy { it.tier } }
    }

    /**
     * Bit layout of a room's furniture varp: (group, shift, bits), groups ascending. Tiers are the
     * cache's option numbers (1-based; 0 = nothing built).
     */
    val furnitureLayout: Map<String, List<Triple<Int, Int, Int>>> by lazy {
        rooms.associate { room ->
            var shift = 0
            val layout =
                optionsByGroup
                    .filterKeys { it.first == room.key }
                    .map { (key, opts) -> key.second to opts.maxOf { it.tier } }
                    .sortedBy { it.first }
                    .map { (group, maxTier) ->
                        val bits = 32 - Integer.numberOfLeadingZeros(maxTier)
                        Triple(group, shift, bits).also { shift += bits }
                    }
            check(shift <= 31) { "Construction: ${room.key} furniture needs $shift bits." }
            room.key to layout
        }
    }

    /** Garden hotspots (besides the centrepiece), hidden outside build mode. */
    val gardenHotspots: List<String> =
        listOf(
            "poh_crude_garden_2",
            "poh_crude_garden_3",
            "poh_crude_garden_4",
            "poh_crude_garden_5",
            "poh_crude_garden_6",
            "poh_crude_garden_7",
            "poh_garden_8",
        )

    /** Nails in the order they are used up (cheapest first). */
    val nails: List<String> =
        listOf(
            "nails_bronze",
            "nails_iron",
            "nails",
            "nails_black",
            "nails_mithril",
            "nails_adamant",
            "nails_rune",
        )

    /**
     * OSRS Wiki "Player-owned house": (level, maximum rooms, yard side length). Rooms may be placed
     * anywhere in the yard; gardens count as rooms.
     */
    private val roomLimits: List<Triple<Int, Int, Int>> =
        listOf(
            Triple(1, 24, 5),
            Triple(15, 24, 6),
            Triple(26, 25, 6),
            Triple(30, 25, 7),
            Triple(32, 26, 7),
            Triple(38, 27, 7),
            Triple(44, 28, 7),
            Triple(45, 28, 8),
            Triple(50, 29, 8),
            Triple(56, 30, 8),
            Triple(60, 30, 9),
            Triple(62, 31, 9),
            Triple(68, 32, 9),
            Triple(74, 33, 9),
            Triple(80, 34, 9),
            Triple(86, 35, 9),
            Triple(92, 36, 9),
            Triple(96, 37, 9),
            Triple(99, 38, 9),
        )

    fun maxRooms(level: Int): Int = roomLimits.last { level >= it.first }.second

    fun yardSize(level: Int): Int = roomLimits.last { level >= it.first }.third

    /** Room slots saved per player (the Wiki maximum). */
    const val MAX_SLOTS = 38
}
